-- ──────────────────────────────────────────────────────────────────────────
-- SINK TABLES (written only by the sink service)
--
-- Every table has a primary key taken from the DATA, not generated by us.
-- Combined with INSERT ... ON CONFLICT, that makes every write idempotent:
-- a redelivered message rewrites the same row instead of adding a duplicate.
-- All timestamps are UTC.
-- ──────────────────────────────────────────────────────────────────────────

CREATE SCHEMA IF NOT EXISTS bronze;
CREATE SCHEMA IF NOT EXISTS quarantine;
CREATE SCHEMA IF NOT EXISTS silver;
CREATE SCHEMA IF NOT EXISTS gold;
CREATE SCHEMA IF NOT EXISTS ops;

-- Every validated event, exactly once (deduplicated on event_id).
CREATE TABLE IF NOT EXISTS bronze.events (
    event_id              VARCHAR PRIMARY KEY,
    event_type            VARCHAR NOT NULL,
    schema_version        INTEGER NOT NULL,
    source_schema_version INTEGER NOT NULL,
    event_time            TIMESTAMP NOT NULL,   -- when it happened (client)
    session_id            VARCHAR NOT NULL,
    user_id               VARCHAR,
    channel               VARCHAR,
    payload               JSON NOT NULL,
    published_at          TIMESTAMP,            -- when the validator published it
    ingested_at           TIMESTAMP NOT NULL    -- when the sink wrote it
);

-- Events that broke their contract, kept verbatim for debugging and replay.
CREATE TABLE IF NOT EXISTS quarantine.invalid_events (
    source_message_id VARCHAR PRIMARY KEY,
    error             VARCHAR NOT NULL,
    raw               VARCHAR NOT NULL,
    ingested_at       TIMESTAMP NOT NULL
);

-- Messages some subscriber could not process after max_delivery_attempts.
CREATE TABLE IF NOT EXISTS quarantine.dead_letters (
    message_id          VARCHAR PRIMARY KEY,
    source_subscription VARCHAR,
    delivery_attempts   INTEGER,
    raw                 VARCHAR NOT NULL,
    ingested_at         TIMESTAMP NOT NULL
);

-- Real-time window results from the aggregator (one row per window).
CREATE TABLE IF NOT EXISTS gold.window_metrics (
    window_start     TIMESTAMP PRIMARY KEY,
    window_end       TIMESTAMP NOT NULL,
    events           INTEGER NOT NULL,
    page_views       INTEGER NOT NULL,
    product_views    INTEGER NOT NULL,
    add_to_carts     INTEGER NOT NULL,
    checkouts        INTEGER NOT NULL,
    orders           INTEGER NOT NULL,
    revenue          DOUBLE  NOT NULL,
    payment_failures INTEGER NOT NULL,
    emitted_at       TIMESTAMP NOT NULL
);

-- Events that arrived after their window had already been emitted.
CREATE TABLE IF NOT EXISTS gold.late_events (
    event_id    VARCHAR PRIMARY KEY,
    event_type  VARCHAR NOT NULL,
    event_time  TIMESTAMP NOT NULL,
    watermark   TIMESTAMP NOT NULL,
    detected_at TIMESTAMP NOT NULL
);

CREATE TABLE IF NOT EXISTS ops.alerts (
    alert_id   VARCHAR PRIMARY KEY,
    alert_type VARCHAR NOT NULL,
    severity   VARCHAR NOT NULL,
    event_id   VARCHAR NOT NULL,
    user_id    VARCHAR,
    details    JSON,
    created_at TIMESTAMP NOT NULL
);
